const raw = typeof query === 'string' ? query : JSON.stringify(query ?? '');
let data;
try {
  data = (query && typeof query === 'object') ? query : JSON.parse(raw);
} catch {
  data = { filename: 'output.txt', content: raw };
}

const requested = String(data.filename || 'output.txt').trim() || 'output.txt';
const safeName = requested
  .replace(/[\\/:*?"<>|]/g, '-')
  .replace(/\.{2,}/g, '.')
  .replace(/-{2,}/g, '-')
  .replace(/^[.\-\s]+/, '')
  .slice(0, 120) || 'output.txt';
const filename = /\.[a-z0-9]{1,8}$/i.test(safeName) ? safeName : safeName + '.txt';
const content = String(data.content ?? '');

if (!content.trim()) {
  return 'ERROR: No content provided. Call with {"filename":"notes.txt","content":"..."}.';
}

const bytes = typeof Buffer !== 'undefined' ? Buffer.byteLength(content, 'utf8') : content.length;
const created = new Date().toISOString();

return [
  'FILE READY: ' + filename,
  'Created: ' + created,
  'Size: ' + bytes + ' bytes',
  '',
  '----- BEGIN FILE CONTENT -----',
  content,
  '----- END FILE CONTENT -----',
  '',
  'Present this content to the user in a fenced code block labeled ' + filename + '.',
].join('\n');

const raw = typeof query === 'string' ? query : JSON.stringify(query ?? '');
let data;
try {
  data = (query && typeof query === 'object') ? query : JSON.parse(raw);
} catch {
  data = { name: 'Generated Workflow', steps: [raw] };
}

const steps = Array.isArray(data.steps) ? data.steps : [];
if (steps.length === 0) {
  return 'ERROR: No steps provided. Call with {"name":"My Workflow","steps":["Step 1","Step 2"]}.';
}

const used = new Set();
function uniqueName(base) {
  const clean = String(base || 'Step').replace(/\s+/g, ' ').trim().slice(0, 60) || 'Step';
  let name = clean;
  let i = 2;
  while (used.has(name)) name = clean + ' ' + i++;
  used.add(name);
  return name;
}

const nodes = [{
  parameters: {},
  name: 'Manual Trigger',
  type: 'n8n-nodes-base.manualTrigger',
  typeVersion: 1,
  position: [0, 0],
}];
const connections = {};
let previous = 'Manual Trigger';

steps.forEach((step, index) => {
  const base = typeof step === 'string' ? step : (step && step.name) || 'Step ' + (index + 1);
  const name = uniqueName(base);
  nodes.push({
    parameters: {},
    name,
    type: 'n8n-nodes-base.noOp',
    typeVersion: 1,
    position: [220 * (index + 1), 0],
  });
  connections[previous] = { main: [[{ node: name, type: 'main', index: 0 }]] };
  previous = name;
});

const workflow = {
  name: String(data.name || 'Generated Workflow').trim().slice(0, 80) || 'Generated Workflow',
  nodes,
  connections,
  active: false,
  settings: { executionOrder: 'v1' },
  pinData: {},
  meta: { templateCredsSetupCompleted: false },
  tags: [],
};

return JSON.stringify(workflow, null, 2);
